contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint preFund) public payable {
        uint before = address(c).balance;
        c.withdrawAll(); if (__ESBMC_reverted()) return;
        assert(before == 0 || (address(c).balance == 0 && c.owner() == address(this)));
    }
}

