// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 preFund) internal {
        uint before = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        assertTrue(before == 0 || (address(c).balance == 0 && c.owner() == address(this)));
    }

    function testFuzz_run(uint256 preFund) public {
        _run(preFund);
    }

    receive() external payable {}
}
